describe("validateCourseVersionForPublish", () => {
  it("passes for a valid course version", () => {
    const resource = approvedImageResource();
    const version = courseVersion({
      units: [
        unit({
          lessons: [
            {
              id: "lesson-1",
              title: "课次一",
              sortOrder: 0,
              activities: [
                activity({
                  id: "activity-1",
                  sortOrder: 0,
                  resources: [resourceRef(resource.id)],
                }),
              ],
            },
          ],
        }),
