import type {
  GlossaryEntry,
  TranslationJob,
  TranslationStatus,
} from "../../../../src/modules/translations/domain/translation.types.js";
import {
  ReviewStatus,
} from "../../../../src/modules/translations/domain/translation.types.js";
import type {
  ListJobsOptions,
  PaginatedResult,
  TranslationRepositoryPort,
} from "../../../../src/modules/translations/ports/translation-repository.port.js";

type GlossaryEntryWithSchool = GlossaryEntry & { schoolId: string };

export class FakeTranslationRepository implements TranslationRepositoryPort {
  private jobs: Map<string, TranslationJob> = new Map();
  private glossaryEntries: Map<string, GlossaryEntryWithSchool> = new Map();
  private nextId = 1;

  async createJob(
    data: Omit<TranslationJob, "id" | "createdAt" | "updatedAt">,
  ): Promise<TranslationJob> {
    const now = new Date();
    const job: TranslationJob = {
      id: `job-${this.nextId++}`,
      schoolId: data.schoolId,
      createdByUserId: data.createdByUserId,
      sourceLanguage: data.sourceLanguage,
      targetLanguage: data.targetLanguage,
      sourceTextHash: data.sourceTextHash,
      sourceTextEncrypted: data.sourceTextEncrypted,
      status: data.status,
      machineResult: data.machineResult,
      revisedResult: data.revisedResult,
      reviewStatus: data.reviewStatus,
      revision: data.revision,
      reviewedByUserId: data.reviewedByUserId,
      reviewedAt: data.reviewedAt,
      glossaryVersion: data.glossaryVersion,
      provider: data.provider,
      providerRequestId: data.providerRequestId,
      providerModel: data.providerModel,
      providerLatencyMs: data.providerLatencyMs,
      errorCode: data.errorCode,
      createdAt: now,
      updatedAt: now,
    };
    this.jobs.set(job.id, job);
    return job;
  }

  async findJobById(
    schoolId: string,
    jobId: string,
  ): Promise<TranslationJob | null> {
    const job = this.jobs.get(jobId);
    return job && job.schoolId === schoolId ? job : null;
  }

  async findJobByIdOnly(jobId: string): Promise<TranslationJob | null> {
    return this.jobs.get(jobId) ?? null;
  }

  async listJobsBySchool(
    schoolId: string,
    options: ListJobsOptions,
  ): Promise<PaginatedResult<TranslationJob>> {
    let items = [...this.jobs.values()].filter(
      (j) => j.schoolId === schoolId,
    );

    if (options.userId) {
      items = items.filter((j) => j.createdByUserId === options.userId);
    }
    if (options.status) {
      items = items.filter((j) => j.status === options.status);
    }

    const limit = options.limit;
    const start = options.cursor
      ? items.findIndex((i) => i.id === options.cursor) + 1
      : 0;
    const slice = items.slice(start, start + limit);
    const hasMore = start + limit < items.length;

    return {
      items: slice,
      nextCursor:
        hasMore && slice.length > 0 ? slice[slice.length - 1]!.id : null,
      hasMore,
    };
  }

  async updateJobResult(
    schoolId: string,
    jobId: string,
    data: {
      status: TranslationStatus;
      machineResult?: string | null;
      provider?: string;
      providerRequestId?: string;
      providerModel?: string;
      providerLatencyMs?: number;
      errorCode?: string;
    },
  ): Promise<TranslationJob | null> {
    const job = this.jobs.get(jobId);
    if (!job || job.schoolId !== schoolId) return null;
    // Do not overwrite APPROVED jobs
    if (job.reviewStatus === ReviewStatus.APPROVED) return job;

    const updated: TranslationJob = {
      ...job,
      status: data.status,
      ...(data.machineResult !== undefined ? { machineResult: data.machineResult } : {}),
      ...(data.provider !== undefined ? { provider: data.provider } : {}),
      ...(data.providerRequestId !== undefined ? { providerRequestId: data.providerRequestId } : {}),
      ...(data.providerModel !== undefined ? { providerModel: data.providerModel } : {}),
      ...(data.providerLatencyMs !== undefined ? { providerLatencyMs: data.providerLatencyMs } : {}),
      ...(data.errorCode !== undefined ? { errorCode: data.errorCode } : {}),
      updatedAt: new Date(),
    };
    this.jobs.set(jobId, updated);
    return updated;
  }

  async updateJobRevision(
    schoolId: string,
    jobId: string,
    data: {
      revisedResult: string;
      reviewStatus: string;
      reviewedByUserId: string;
      reviewedAt: Date;
      revision: number;
    },
  ): Promise<TranslationJob | null> {
    const job = this.jobs.get(jobId);
    if (!job || job.schoolId !== schoolId) return null;
    // Optimistic concurrency check
    if (job.revision !== data.revision) return null;

    const updated: TranslationJob = {
      ...job,
      revisedResult: data.revisedResult,
      reviewStatus: data.reviewStatus as ReviewStatus,
      reviewedByUserId: data.reviewedByUserId,
      reviewedAt: data.reviewedAt,
      revision: job.revision + 1,
      updatedAt: new Date(),
    };
    this.jobs.set(jobId, updated);
    return updated;
  }

  async listGlossary(
    schoolId: string,
    version?: number,
  ): Promise<readonly GlossaryEntry[]> {
    let items = [...this.glossaryEntries.values()].filter(
      (e) => e.schoolId === schoolId,
    );
    if (version !== undefined) {
      items = items.filter((e) => e.version === version);
    }
    // Strip schoolId from results — GlossaryEntry does not carry it
    return items.map(({ schoolId: _sid, ...rest }) => rest);
  }

  async findGlossaryByVersion(
    version: number,
  ): Promise<readonly GlossaryEntry[]> {
    const items = [...this.glossaryEntries.values()].filter(
      (e) => e.version === version,
    );
    return items.map(({ schoolId: _sid, ...rest }) => rest);
  }

  /** Test helper: seed a job into the repository. */
  addJob(job: TranslationJob): void {
    this.jobs.set(job.id, job);
  }

  /** Test helper: seed a glossary entry into the repository. */
  addGlossaryEntry(entry: GlossaryEntryWithSchool): void {
    this.glossaryEntries.set(entry.id, entry);
  }
}

import type { AuthContext } from "../../../../src/common/security/auth.types.js";
import { createAuthContext } from "../../../../src/common/security/auth-context.js";
import { MembershipRole, MembershipStatus } from "../../../../src/common/security/index.js";

export function studentPrincipal(overrides: { userId?: string } = {}) {
  return {
    userId: overrides.userId ?? "student-1",
    roles: [MembershipRole.STUDENT] as readonly MembershipRole[],
    membershipStatus: MembershipStatus.ACTIVE,
    source: "test",
  };
}

export function teacherPrincipal(overrides: { userId?: string } = {}) {
  return {
    userId: overrides.userId ?? "teacher-1",
    roles: [MembershipRole.TEACHER] as readonly MembershipRole[],
    membershipStatus: MembershipStatus.ACTIVE,
    source: "test",
  };
}

export function schoolAdminPrincipal(overrides: { userId?: string } = {}) {
  return {
    userId: overrides.userId ?? "admin-1",
    roles: [MembershipRole.SCHOOL_ADMIN] as readonly MembershipRole[],
    membershipStatus: MembershipStatus.ACTIVE,
    source: "test",
  };
}

export function platformAdminPrincipal(overrides: { userId?: string } = {}) {
  return {
    userId: overrides.userId ?? "platform-admin-1",
    roles: [MembershipRole.PLATFORM_ADMIN] as readonly MembershipRole[],
    membershipStatus: MembershipStatus.ACTIVE,
    source: "test",
  };
}

export function studentAuth(schoolId = "school-1", overrides: { userId?: string } = {}) {
  return createAuthContext("req-1", studentPrincipal(overrides), { schoolId });
}

export function teacherAuth(schoolId = "school-1", overrides: { userId?: string } = {}) {
  return createAuthContext("req-1", teacherPrincipal(overrides), { schoolId });
}

export function schoolAdminAuth(schoolId = "school-1", overrides: { userId?: string } = {}) {
  return createAuthContext("req-1", schoolAdminPrincipal(overrides), { schoolId });
}

export function platformAdminAuth(schoolId = "school-1", overrides: { userId?: string } = {}) {
  return createAuthContext("req-1", platformAdminPrincipal(overrides), { schoolId });
}

/** Create an auth context with a suspended membership (not active). */
export function suspendedStudentAuth(schoolId = "school-1") {
  return createAuthContext(
    "req-1",
    {
      userId: "suspended-student-1",
      roles: [MembershipRole.STUDENT] as readonly MembershipRole[],
      membershipStatus: MembershipStatus.SUSPENDED,
      source: "test",
    },
    { schoolId },
  );
}

import { describe, expect, it, vi } from "vitest";
import {
  TranslationConflictException,
  TranslationForbiddenException,
  TranslationInputTooLongException,
  TranslationNotFoundException,
  TranslationRateLimitedException,
  TranslationSameLanguageException,
  TranslationUnavailableException,
} from "../../../src/modules/translations/domain/translation.errors.js";
import type { TranslationCryptoPort } from "../../../src/modules/translations/crypto/aes-gcm.crypto.js";
import {
  ReviewStatus,
  SupportedLanguage,
  TranslationStatus,
} from "../../../src/modules/translations/domain/translation.types.js";
import type { TranslationProviderPort } from "../../../src/modules/translations/provider/translation-provider.adapter.js";
import type { TranslationRateLimiterPort } from "../../../src/modules/translations/rate-limit/translation-rate-limit.js";
import { UnavailableTranslationRepository } from "../../../src/modules/translations/ports/unavailable-translation.repository.js";
import { TranslationsService } from "../../../src/modules/translations/translations.service.js";
import { FakeTranslationRepository } from "./fakes/fake-translation.repository.js";
import { completedJob, translationJob } from "./fixtures/translations.js";
import {
  schoolAdminAuth,
  studentAuth,
  suspendedStudentAuth,
  teacherAuth,
  platformAdminAuth,
} from "./fixtures/users.js";

// ---------------------------------------------------------------------------
// Fake dependencies for service constructor
// ---------------------------------------------------------------------------

class FakeCrypto implements TranslationCryptoPort {
  async encrypt(plaintext: string): Promise<string> {
    return `enc:${plaintext}`;
  }
  async decrypt(ciphertext: string): Promise<string> {
    return ciphertext.replace(/^enc:/, "");
  }
}

class FakeRateLimiter implements TranslationRateLimiterPort {
  async checkRateLimit(_userId: string): Promise<void> {
    // No-op by default; tests can override via subclass or flag
  }
}

class ThrowingRateLimiter implements TranslationRateLimiterPort {
  async checkRateLimit(_userId: string): Promise<void> {
    throw new TranslationRateLimitedException();
  }
}

class FakeProvider implements TranslationProviderPort {
  async translate(
    _sourceLang: SupportedLanguage,
    _targetLang: SupportedLanguage,
    _text: string,
  ) {
    return {
      resultText: "mock-translation",
      requestId: "req-1",
      model: "fake-model",
      latencyMs: 100,
    };
  }
}

class UnavailableProvider implements TranslationProviderPort {
  async translate() {
    throw new TranslationUnavailableException("provider not configured");
  }
}

function createService(options?: {
  repo?: FakeTranslationRepository;
  rateLimiter?: TranslationRateLimiterPort;
  provider?: TranslationProviderPort;
}) {
  const repo = options?.repo ?? new FakeTranslationRepository();
  return {
    service: new TranslationsService(
      repo,
      new FakeCrypto(),
      options?.rateLimiter ?? new FakeRateLimiter(),
      options?.provider ?? new FakeProvider(),
    ),
    repo,
  };
}

const schoolId = "school-1";

// ---------------------------------------------------------------------------
// createTranslation
// ---------------------------------------------------------------------------
describe("TranslationsService", () => {
  describe("createTranslation", () => {
    it("allows TEACHER to create a translation", async () => {
      const { service } = createService();
      const auth = teacherAuth(schoolId);

      const result = await service.createTranslation(
        auth,
        schoolId,
        SupportedLanguage.BO,
        SupportedLanguage.ZH,
        "བཀྲ་ཤིས་བདེ་ལེགས།",
      );

      expect(result.status).toBe(TranslationStatus.CREATED);
      expect(result.sourceLanguage).toBe(SupportedLanguage.BO);
      expect(result.targetLanguage).toBe(SupportedLanguage.ZH);
    });

    it("allows STUDENT to create a translation (student is a school member)", async () => {
      const { service } = createService();
      const auth = studentAuth(schoolId);

      const result = await service.createTranslation(
        auth,
        schoolId,
        SupportedLanguage.BO,
        SupportedLanguage.ZH,
        "མཚམས་མཆོད།",
      );

      expect(result.status).toBe(TranslationStatus.CREATED);
    });

    it("denies cross-tenant create", async () => {
      const { service } = createService();
      const auth = studentAuth("school-2");

      await expect(
        service.createTranslation(
          auth,
          schoolId,
          SupportedLanguage.BO,
          SupportedLanguage.ZH,
          "test",
        ),
      ).rejects.toThrow(TranslationForbiddenException);
    });

    it("denies suspended user from creating translation", async () => {
      const { service } = createService();
      const auth = suspendedStudentAuth(schoolId);

      await expect(
        service.createTranslation(
          auth,
          schoolId,
          SupportedLanguage.BO,
          SupportedLanguage.ZH,
          "test",
        ),
      ).rejects.toThrow(TranslationForbiddenException);
    });

    it("rejects source text exceeding 5000 characters", async () => {
      const { service } = createService();
      const auth = teacherAuth(schoolId);
      const longText = "a".repeat(5001);

      await expect(
        service.createTranslation(
          auth,
          schoolId,
          SupportedLanguage.BO,
          SupportedLanguage.ZH,
          longText,
        ),
      ).rejects.toThrow(TranslationInputTooLongException);
    });

    it("accepts source text at exactly 5000 characters", async () => {
      const { service } = createService();
      const auth = teacherAuth(schoolId);
      const maxLengthText = "a".repeat(5000);

      const result = await service.createTranslation(
        auth,
        schoolId,
        SupportedLanguage.BO,
        SupportedLanguage.ZH,
        maxLengthText,
      );

      expect(result.status).toBe(TranslationStatus.CREATED);
    });

    it("rejects same-language translation", async () => {
      const { service } = createService();
      const auth = teacherAuth(schoolId);

      await expect(
        service.createTranslation(
          auth,
          schoolId,
          SupportedLanguage.BO,
          SupportedLanguage.BO,
          "test",
        ),
      ).rejects.toThrow(TranslationSameLanguageException);
    });

    it("never leaks sourceTextEncrypted in the response", async () => {
      const { service } = createService();
      const auth = teacherAuth(schoolId);

      const result = await service.createTranslation(
        auth,
        schoolId,
        SupportedLanguage.BO,
        SupportedLanguage.ZH,
        "secret text",
      );

      expect(
        (result as Record<string, unknown>)["sourceTextEncrypted"],
      ).toBeUndefined();
    });

    it("rate limits when exceeded", async () => {
      const { service } = createService({
        rateLimiter: new ThrowingRateLimiter(),
      });
      const auth = teacherAuth(schoolId);

      await expect(
        service.createTranslation(
          auth,
          schoolId,
          SupportedLanguage.BO,
          SupportedLanguage.ZH,
          "test",
        ),
      ).rejects.toThrow(TranslationRateLimitedException);
    });
  });

  // -------------------------------------------------------------------------
  // getJobStatus
  // -------------------------------------------------------------------------
  describe("getJobStatus", () => {
    it("returns the real status of a job", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        status: TranslationStatus.PROCESSING,
      });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);

      expect(result.status).toBe(TranslationStatus.PROCESSING);
    });

    it("returns COMPLETED status with machineResult", async () => {
      const { service, repo } = createService();
      const job = completedJob({ schoolId });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);

      expect(result.status).toBe(TranslationStatus.COMPLETED);
      expect(result.machineResult).toBe("翻译结果文本");
    });

    it("returns PROVIDER_UNAVAILABLE status without fabricating completion", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        status: TranslationStatus.PROVIDER_UNAVAILABLE,
        errorCode: "PROVIDER_UNAVAILABLE",
      });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);

      expect(result.status).toBe(TranslationStatus.PROVIDER_UNAVAILABLE);
      expect(result.machineResult).toBeNull();
    });

    it("throws TranslationNotFoundException for missing job", async () => {
      const { service } = createService();
      const auth = teacherAuth(schoolId);

      await expect(
        service.getJobStatus(auth, schoolId, "nonexistent-id"),
      ).rejects.toThrow(TranslationNotFoundException);
    });

    it("denies cross-tenant access to a job", async () => {
      const { service, repo } = createService();
      const job = translationJob({ schoolId });
      repo.addJob(job);
      const auth = teacherAuth("school-2");

      await expect(
        service.getJobStatus(auth, schoolId, job.id),
      ).rejects.toThrow(TranslationForbiddenException);
    });

    it("denies student access to another student's job", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        createdByUserId: "other-student",
      });
      repo.addJob(job);
      // studentAuth defaults to userId "student-1"
      const auth = studentAuth(schoolId);

      await expect(
        service.getJobStatus(auth, schoolId, job.id),
      ).rejects.toThrow(TranslationForbiddenException);
    });

    it("allows student to view their own job", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        createdByUserId: "student-1",
      });
      repo.addJob(job);
      const auth = studentAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);

      expect(result.id).toBe(job.id);
    });

    it("never includes sourceTextEncrypted in the response", async () => {
      const { service, repo } = createService();
      const job = translationJob({ schoolId });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);

      expect(
        (result as Record<string, unknown>)["sourceTextEncrypted"],
      ).toBeUndefined();
    });

    it("sanitizes unknown error codes to INTERNAL_ERROR", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        status: TranslationStatus.FAILED,
        errorCode: "AWS_SECRET_INTERNAL_STACK_TRACE",
      });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);

      expect(result.errorCode).toBe("INTERNAL_ERROR");
    });
  });

  // -------------------------------------------------------------------------
  // listMyJobs
  // -------------------------------------------------------------------------
  describe("listMyJobs", () => {
    it("returns jobs filtered by userId", async () => {
      const { service, repo } = createService();
      const job1 = translationJob({ schoolId, createdByUserId: "student-1" });
      const job2 = translationJob({ schoolId, createdByUserId: "other-user" });
      repo.addJob(job1);
      repo.addJob(job2);
      const auth = studentAuth(schoolId);

      const result = await service.listMyJobs(auth, schoolId, { limit: 10 });

      expect(result.items).toHaveLength(1);
      expect(result.items[0]!.id).toBe(job1.id);
    });

    it("denies cross-tenant listing", async () => {
      const { service } = createService();
      const auth = studentAuth("school-2");

      await expect(
        service.listMyJobs(auth, schoolId, { limit: 10 }),
      ).rejects.toThrow(TranslationForbiddenException);
    });

    it("denies suspended user from listing own jobs", async () => {
      const { service } = createService();
      const auth = suspendedStudentAuth(schoolId);

      await expect(
        service.listMyJobs(auth, schoolId, { limit: 10 }),
      ).rejects.toThrow(TranslationForbiddenException);
    });
  });

  // -------------------------------------------------------------------------
  // listJobs (admin-level)
  // -------------------------------------------------------------------------
  describe("listJobs", () => {
    it("allows TEACHER to list all jobs", async () => {
      const { service, repo } = createService();
      repo.addJob(translationJob({ schoolId }));
      const auth = teacherAuth(schoolId);

      const result = await service.listJobs(auth, schoolId, { limit: 10 });

      expect(result.items).toHaveLength(1);
    });

    it("allows SCHOOL_ADMIN to list all jobs", async () => {
      const { service, repo } = createService();
      repo.addJob(translationJob({ schoolId }));
      const auth = schoolAdminAuth(schoolId);

      const result = await service.listJobs(auth, schoolId, { limit: 10 });

      expect(result.items).toHaveLength(1);
    });

    it("denies STUDENT from listing all jobs", async () => {
      const { service } = createService();
      const auth = studentAuth(schoolId);

      await expect(
        service.listJobs(auth, schoolId, { limit: 10 }),
      ).rejects.toThrow(TranslationForbiddenException);
    });

    it("denies cross-tenant listing", async () => {
      const { service } = createService();
      const auth = teacherAuth("school-2");

      await expect(
        service.listJobs(auth, schoolId, { limit: 10 }),
      ).rejects.toThrow(TranslationForbiddenException);
    });
  });

  // -------------------------------------------------------------------------
  // reviseJob
  // -------------------------------------------------------------------------
  describe("reviseJob", () => {
    it("allows TEACHER to revise a job with correct revision", async () => {
      const { service, repo } = createService();
      const job = completedJob({ schoolId, revision: 0 });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.reviseJob(
        auth,
        schoolId,
        job.id,
        "修订后的翻译",
        0,
      );

      expect(result.revisedResult).toBe("修订后的翻译");
      expect(result.revision).toBe(1);
      expect(result.reviewStatus).toBe(ReviewStatus.NEEDS_REVIEW);
    });

    it("throws ConflictException on revision mismatch (409)", async () => {
      const { service, repo } = createService();
      const job = completedJob({ schoolId, revision: 2 });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      await expect(
        service.reviseJob(auth, schoolId, job.id, "修改", 0),
      ).rejects.toThrow(TranslationConflictException);
    });

    it("denies STUDENT from revising", async () => {
      const { service, repo } = createService();
      const job = completedJob({ schoolId, revision: 0 });
      repo.addJob(job);
      const auth = studentAuth(schoolId);

      await expect(
        service.reviseJob(auth, schoolId, job.id, "修改", 0),
      ).rejects.toThrow(TranslationForbiddenException);
