  // -------------------------------------------------------------------------
  // approveJob
  // -------------------------------------------------------------------------
  describe("approveJob", () => {
    it("allows TEACHER to approve a job", async () => {
      const { service, repo } = createService();
      const job = completedJob({ schoolId, revision: 1, revisedResult: "修订结果" });
      repo.addJob(job);
