  // -------------------------------------------------------------------------
  // Unavailable repository — fail-closed
  // -------------------------------------------------------------------------
  describe("fail-closed when repository is unavailable", () => {
    it("throws TranslationUnavailableException on createTranslation", async () => {
      const service = new TranslationsService(
