        ),
      ).rejects.toThrow(TranslationUnavailableException);
    });

    it("throws TranslationUnavailableException on getJobStatus", async () => {
      const service = new TranslationsService(
        new UnavailableTranslationRepository(),
        new FakeCrypto(),
        new FakeRateLimiter(),
        new FakeProvider(),
      );
      const auth = teacherAuth(schoolId);

      await expect(
        service.getJobStatus(auth, schoolId, "any-id"),
      ).rejects.toThrow(TranslationUnavailableException);
    });

    it("throws TranslationUnavailableException on listMyJobs", async () => {
      const service = new TranslationsService(
        new UnavailableTranslationRepository(),
        new FakeCrypto(),
        new FakeRateLimiter(),
        new FakeProvider(),
      );
      const auth = studentAuth(schoolId);

      await expect(
        service.listMyJobs(auth, schoolId, { limit: 10 }),
      ).rejects.toThrow(TranslationUnavailableException);
    });

    it("throws TranslationUnavailableException on listJobs", async () => {
      const service = new TranslationsService(
        new UnavailableTranslationRepository(),
        new FakeCrypto(),
        new FakeRateLimiter(),
        new FakeProvider(),
      );
      const auth = teacherAuth(schoolId);

      await expect(
        service.listJobs(auth, schoolId, { limit: 10 }),
      ).rejects.toThrow(TranslationUnavailableException);
    });

    it("never returns fake completed results when provider is unavailable", async () => {
      const { service, repo } = createService({
        provider: new UnavailableProvider(),
      });
      const auth = teacherAuth(schoolId);

      // Create will succeed but the async processTranslation will mark FAILED
      const result = await service.createTranslation(
        auth,
        schoolId,
        SupportedLanguage.BO,
        SupportedLanguage.ZH,
        "test",
      );

      // Job should be CREATED initially (fire-and-forget processing)
      expect(result.status).toBe(TranslationStatus.CREATED);
      // No fake result
      expect(result.machineResult).toBeNull();
    });
  });

  // -------------------------------------------------------------------------
  // Cross-tenant access
  // -------------------------------------------------------------------------
  describe("cross-tenant access", () => {
    it("denies access to a different school for every operation", async () => {
      const { service, repo } = createService();
      const job = translationJob({ schoolId });
      repo.addJob(job);
      const otherSchoolAuth = teacherAuth("school-2");

      await expect(
        service.createTranslation(
          otherSchoolAuth,
          schoolId,
          SupportedLanguage.BO,
          SupportedLanguage.ZH,
          "test",
        ),
      ).rejects.toThrow(TranslationForbiddenException);

      await expect(
        service.getJobStatus(otherSchoolAuth, schoolId, job.id),
      ).rejects.toThrow(TranslationForbiddenException);

      await expect(
        service.listMyJobs(otherSchoolAuth, schoolId, { limit: 10 }),
      ).rejects.toThrow(TranslationForbiddenException);

      await expect(
        service.listJobs(otherSchoolAuth, schoolId, { limit: 10 }),
      ).rejects.toThrow(TranslationForbiddenException);
    });
  });

  // -------------------------------------------------------------------------
  // PLATFORM_ADMIN can access any school
  // -------------------------------------------------------------------------
  describe("PLATFORM_ADMIN access", () => {
    it("can create translation in any school", async () => {
      const { service } = createService();
      const auth = platformAdminAuth("school-999");

      const result = await service.createTranslation(
        auth,
        schoolId,
        SupportedLanguage.BO,
        SupportedLanguage.ZH,
        "admin test",
      );

      expect(result.status).toBe(TranslationStatus.CREATED);
    });
  });

  // -------------------------------------------------------------------------
  // Rate limiting
  // -------------------------------------------------------------------------
  describe("rate limiting", () => {
    it("throws TranslationRateLimitedException when rate limit is exceeded", async () => {
      const error = new TranslationRateLimitedException();
      expect(error).toBeInstanceOf(TranslationRateLimitedException);
      expect(error.getStatus()).toBe(429);

      const body = error.getResponse() as Record<string, unknown>;
      expect(body.code).toBe("TRANSLATION_RATE_LIMITED");
    });

    it("propagates rate limit exception from limiter", async () => {
      const { service } = createService({
        rateLimiter: new ThrowingRateLimiter(),
      });
      const auth = teacherAuth(schoolId);

      await expect(
        service.createTranslation(
          auth,
          schoolId,
          SupportedLanguage.BO,
          SupportedLanguage.ZH,
          "test",
        ),
      ).rejects.toThrow(TranslationRateLimitedException);
    });
  });

  // -------------------------------------------------------------------------
  // Error sanitization
  // -------------------------------------------------------------------------
  describe("error sanitization", () => {
    it("response never includes sourceTextEncrypted", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        sourceTextEncrypted: "HIGHLY_SENSITIVE_ENCRYPTED_DATA",
      });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);
      const keys = Object.keys(result);

      expect(keys).not.toContain("sourceTextEncrypted");
    });

    it("response never includes provider key in the response", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        provider: "aws-translate",
      });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);
      const keys = Object.keys(result);

      expect(keys).not.toContain("provider");
    });

    it("sanitizes unknown error codes to INTERNAL_ERROR", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        status: TranslationStatus.FAILED,
        errorCode: "PROVIDER_INTERNAL_AWS_ERROR_12345",
      });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      const result = await service.getJobStatus(auth, schoolId, job.id);

      expect(result.errorCode).toBe("INTERNAL_ERROR");
    });

    it("preserves known safe error codes", async () => {
      const safeCodes = [
        "PROVIDER_UNAVAILABLE",
        "QUOTA_EXCEEDED",
        "INVALID_INPUT",
        "INTERNAL_ERROR",
      ] as const;

      for (const code of safeCodes) {
        const { service, repo } = createService();
        const job = translationJob({
          schoolId,
          status: TranslationStatus.FAILED,
          errorCode: code,
        });
        repo.addJob(job);
        const auth = teacherAuth(schoolId);

        const result = await service.getJobStatus(auth, schoolId, job.id);

        expect(result.errorCode).toBe(code);
      }
    });
  });

  // -------------------------------------------------------------------------
  // Provider retry protection
  // -------------------------------------------------------------------------
  describe("provider retry protection", () => {
    it("does not overwrite APPROVED job with provider retry", async () => {
      const { service, repo } = createService();
      const job = translationJob({
        schoolId,
        status: TranslationStatus.COMPLETED,
        machineResult: "original",
        reviewStatus: ReviewStatus.APPROVED,
        revision: 1,
      });
      repo.addJob(job);
      const auth = teacherAuth(schoolId);

      // Try to update via the internal method (simulating provider retry)
      const result = await service.updateJobResultFromWorker(job.id, {
        status: TranslationStatus.COMPLETED,
        machineResult: "overwritten-by-retry",
      });

      // The APPROVED job should be returned unchanged
      expect(result.machineResult).toBe("original");
      expect(result.reviewStatus).toBe(ReviewStatus.APPROVED);
    });
  });
});

import type { Volunteer, VolunteerSummary, VolunteerServiceTask, IncidentReport, VolunteerStatus } from "../../../../src/modules/volunteers/domain/volunteer.types.js";
import type { VolunteerRepositoryPort, ListVolunteersOptions, ListServiceTasksOptions, PaginatedResult, CreateVolunteerData, CreateIncidentData } from "../../../../src/modules/volunteers/ports/volunteer-repository.port.js";

export class FakeVolunteerRepository implements VolunteerRepositoryPort {
  private volunteers: Map<string, Volunteer> = new Map();
  private serviceTasks: Map<string, VolunteerServiceTask> = new Map();
  private incidents: Map<string, IncidentReport> = new Map();
  private nextId = 1;

  async findById(schoolId: string, volunteerId: string): Promise<Volunteer | null> {
    const v = this.volunteers.get(volunteerId);
    return v && v.schoolId === schoolId ? v : null;
  }

  async findByUserId(schoolId: string, userId: string): Promise<Volunteer | null> {
    for (const v of this.volunteers.values()) {
      if (v.schoolId === schoolId && v.userId === userId) return v;
    }
    return null;
  }

  async list(schoolId: string, options: ListVolunteersOptions): Promise<PaginatedResult<VolunteerSummary>> {
    let items = [...this.volunteers.values()]
      .filter((v) => v.schoolId === schoolId)
      .map((v): VolunteerSummary => ({
        id: v.id,
        schoolId: v.schoolId,
        userId: v.userId,
        displayName: v.displayName,
        status: v.status,
        appliedAt: v.appliedAt,
      }));

    if (options.status) {
      items = items.filter((v) => v.status === options.status);
    }

    const limit = options.limit;
    const start = options.cursor ? items.findIndex((i) => i.id === options.cursor) + 1 : 0;
    const slice = items.slice(start, start + limit);
    const hasMore = start + limit < items.length;

    return {
      items: slice,
      nextCursor: hasMore && slice.length > 0 ? slice[slice.length - 1].id : null,
      hasMore,
    };
  }

  async create(schoolId: string, data: CreateVolunteerData): Promise<Volunteer> {
    const now = new Date();
    const v: Volunteer = {
      id: `vol-${this.nextId++}`,
      schoolId,
      userId: data.userId,
      displayName: data.displayName,
      phone: data.phone,
      email: data.email,
      experience: data.experience,
      status: "APPLIED" as VolunteerStatus,
      qualifications: [],
      appliedAt: now,
      revision: 1,
      createdAt: now,
      updatedAt: now,
    };
    this.volunteers.set(v.id, v);
    return v;
  }

  async updateStatus(schoolId: string, volunteerId: string, status: VolunteerStatus, _revision: number, extra?: { suspendedReason?: string; qualifiedAt?: Date }): Promise<Volunteer> {
    const v = this.volunteers.get(volunteerId);
    if (!v || v.schoolId !== schoolId) throw new Error("not found");
    const updated = { ...v, status, updatedAt: new Date(), ...extra };
    this.volunteers.set(volunteerId, updated);
    return updated;
  }

  async listServiceTasks(schoolId: string, options: ListServiceTasksOptions): Promise<PaginatedResult<VolunteerServiceTask>> {
    let items = [...this.serviceTasks.values()].filter((t) => t.schoolId === schoolId);
    if (options.assignedVolunteerId) {
      items = items.filter((t) => t.assignedVolunteerId === options.assignedVolunteerId);
    }
    if (options.status) {
      items = items.filter((t) => t.status === options.status);
    }
    const limit = options.limit;
    const slice = items.slice(0, limit);
    return { items: slice, nextCursor: null, hasMore: false };
  }

  async findServiceTaskById(schoolId: string, taskId: string): Promise<VolunteerServiceTask | null> {
    const t = this.serviceTasks.get(taskId);
    return t && t.schoolId === schoolId ? t : null;
  }

  async assignServiceTask(schoolId: string, taskId: string, volunteerId: string): Promise<VolunteerServiceTask> {
    const t = this.serviceTasks.get(taskId);
    if (!t || t.schoolId !== schoolId) throw new Error("not found");
    const updated = { ...t, assignedVolunteerId: volunteerId, status: "ASSIGNED", updatedAt: new Date() };
    this.serviceTasks.set(taskId, updated);
    return updated;
  }

  async createIncidentReport(schoolId: string, data: CreateIncidentData): Promise<IncidentReport> {
    const now = new Date();
    const inc: IncidentReport = {
      id: `inc-${this.nextId++}`,
      schoolId,
      type: data.type,
      severity: data.severity,
      description: data.description,
      immediateAction: data.immediateAction,
      studentRef: data.studentRef,
      status: "OPEN",
      reportedBy: data.reportedBy,
      createdAt: now,
      updatedAt: now,
    };
    this.incidents.set(inc.id, inc);
    return inc;
  }

  async findIncidentById(schoolId: string, incidentId: string): Promise<IncidentReport | null> {
    const i = this.incidents.get(incidentId);
    return i && i.schoolId === schoolId ? i : null;
  }

  async listIncidents(schoolId: string, options: { severity?: string; status?: string; limit: number; cursor?: string }): Promise<PaginatedResult<IncidentReport>> {
    let items = [...this.incidents.values()].filter((i) => i.schoolId === schoolId);
    if (options.severity) items = items.filter((i) => i.severity === options.severity);
    if (options.status) items = items.filter((i) => i.status === options.status);
    const slice = items.slice(0, options.limit);
    return { items: slice, nextCursor: null, hasMore: false };
  }

  addVolunteer(v: Volunteer): void {
    this.volunteers.set(v.id, v);
  }

  addServiceTask(t: VolunteerServiceTask): void {
    this.serviceTasks.set(t.id, t);
  }
}

