        auth,
        schoolId,
        v.id,
        VolunteerStatus.QUALIFIED,
        v.revision,
      );

      expect(result.status).toBe("QUALIFIED");
      expect(result.qualifiedAt).toBeDefined();
    });
  });

  describe("service tasks", () => {
